/* SudarshanAshtra - Cyber Crime Case Analysis */
:root{
  --bg:#0a0f1c; --surface-1:#111827; --surface-2:#162033; --surface-3:#1e2a42;
  --border:#26344f; --text-primary:#eef2f8; --text-secondary:#b4bfd2; --text-muted:#7f8ba3;
  --accent:#3987e5; --accent-2:#d95926; --good:#1baf7a; --warn:#c98500; --bad:#e66767;
  --s1:#3987e5; --s2:#d95926; --s3:#199e70; --s4:#c98500; --s5:#d55181; --s6:#008300; --s7:#9085e9; --s8:#e66767;
  --grid:#22304a; --shadow:0 6px 24px rgba(0,0,0,.35);
  --radius:14px; color-scheme:dark;
}
:root[data-theme="light"]{
  --bg:#eef2f8; --surface-1:#ffffff; --surface-2:#f6f8fc; --surface-3:#e8edf5;
  --border:#d9dde3; --text-primary:#0b0b0b; --text-secondary:#52514e; --text-muted:#76757a;
  --accent:#2a78d6; --accent-2:#eb6834; --good:#12855c; --warn:#a86f00; --bad:#c83a39;
  --s1:#2a78d6; --s2:#eb6834; --s3:#1baf7a; --s4:#eda100; --s5:#e87ba4; --s6:#008300; --s7:#6250d6; --s8:#e34948;
  --grid:#e3e8f0; --shadow:0 4px 18px rgba(20,40,80,.08); color-scheme:light;
}
*{box-sizing:border-box}
html,body{margin:0;height:100%;background:var(--bg);color:var(--text-primary);font:14px/1.45 "Segoe UI",system-ui,-apple-system,Roboto,"Noto Sans",Arial,sans-serif}
a{color:var(--accent)}
button,input,select,textarea{font:inherit;color:inherit}
input,select,textarea{background:var(--surface-2);border:1px solid var(--border);border-radius:7px;padding:7px 10px;outline:none}
input:focus,select:focus,textarea:focus{border-color:var(--accent);box-shadow:0 0 0 2px color-mix(in srgb,var(--accent) 30%,transparent)}
textarea{width:100%;min-height:120px;resize:vertical;font-family:Consolas,"Courier New",monospace;font-size:13px}
label{color:var(--text-secondary);font-size:12.5px}
.btn{background:var(--surface-3);border:1px solid var(--border);border-radius:7px;padding:7px 13px;cursor:pointer;white-space:nowrap;display:inline-flex;align-items:center;gap:6px}
.btn:hover{border-color:var(--accent)}
.btn.primary{background:var(--accent);border-color:var(--accent);color:#fff}
.btn.danger{background:transparent;border-color:var(--bad);color:var(--bad)}
.btn.sm{padding:4px 9px;font-size:12.5px}
.btn:disabled{opacity:.5;cursor:not-allowed}
.hidden{display:none!important}
.muted{color:var(--text-muted)} .small{font-size:12px}
.mono{font-family:Consolas,"Courier New",monospace}
.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}
.grow{flex:1}
.spacer{flex:1}

/* Login */
#login{position:fixed;inset:0;display:flex;align-items:center;justify-content:center;
  background:radial-gradient(1200px 600px at 20% 10%,color-mix(in srgb,var(--accent) 22%,transparent),transparent),
  radial-gradient(900px 500px at 90% 90%,color-mix(in srgb,var(--accent-2) 16%,transparent),transparent),var(--bg)}
.login-card{width:380px;max-width:92vw;background:var(--surface-1);border:1px solid var(--border);border-radius:16px;padding:30px;box-shadow:var(--shadow)}
.login-card h1{margin:10px 0 2px;font-size:24px;letter-spacing:.5px}
.login-card .field{display:flex;flex-direction:column;gap:5px;margin:14px 0}
.login-card input{padding:10px 12px}
.logo{width:58px;height:58px}
.err{color:var(--bad);min-height:20px;font-size:13px}

/* Layout */
#app{display:grid;grid-template-columns:232px 1fr;grid-template-rows:56px 1fr;height:100vh}
#topbar{grid-column:1/3;display:flex;align-items:center;gap:12px;padding:0 16px;background:var(--surface-1);border-bottom:1px solid var(--border)}
#topbar .brand{display:flex;align-items:center;gap:9px;font-weight:700;font-size:17px;min-width:200px}
#topbar .brand svg{width:30px;height:30px}
#topbar select{max-width:280px}
#gsearch{width:280px}
#sidebar{background:var(--surface-1);border-right:1px solid var(--border);padding:12px 10px;overflow:auto}
.nav-item{display:flex;align-items:center;gap:10px;padding:10px 12px;border-radius:8px;cursor:pointer;color:var(--text-secondary);margin-bottom:3px;user-select:none}
.nav-item:hover{background:var(--surface-2);color:var(--text-primary)}
.nav-item.active{background:color-mix(in srgb,var(--accent) 18%,transparent);color:var(--text-primary);font-weight:600}
.nav-item .num{display:inline-flex;width:22px;height:22px;border-radius:6px;background:var(--surface-3);align-items:center;justify-content:center;font-size:12px}
.nav-item.active .num{background:var(--accent);color:#fff}
.nav-sep{height:1px;background:var(--border);margin:10px 4px}
.side-note{font-size:11.5px;color:var(--text-muted);padding:8px 6px;line-height:1.4}
#main{overflow:auto;padding:18px 22px 40px}
.page-title{display:flex;align-items:center;gap:12px;margin:0 0 14px}
.page-title h2{margin:0;font-size:21px}
.tabs{display:flex;gap:4px;border-bottom:1px solid var(--border);margin-bottom:16px;flex-wrap:wrap}
.tab{padding:9px 14px;cursor:pointer;color:var(--text-secondary);border-bottom:2px solid transparent;margin-bottom:-1px;user-select:none}
.tab:hover{color:var(--text-primary)}
.tab.active{color:var(--text-primary);border-bottom-color:var(--accent);font-weight:600}

.card{background:var(--surface-1);border:1px solid var(--border);border-radius:var(--radius);padding:16px;margin-bottom:16px}
.card h3{margin:0 0 4px;font-size:15.5px}
.card .sub{color:var(--text-muted);font-size:12.5px;margin-bottom:12px}
.grid{display:grid;gap:16px}
.g2{grid-template-columns:repeat(auto-fit,minmax(420px,1fr))}
.g3{grid-template-columns:repeat(auto-fit,minmax(300px,1fr))}
.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:12px;margin-bottom:16px}
.kpi{background:var(--surface-1);border:1px solid var(--border);border-radius:var(--radius);padding:14px 16px}
.kpi .label{color:var(--text-secondary);font-size:12.5px}
.kpi .value{font-size:24px;font-weight:700;margin-top:4px;letter-spacing:.2px}
.kpi .hint{color:var(--text-muted);font-size:11.5px;margin-top:2px}

/* Tables */
.tbl-wrap{overflow:auto;max-height:560px;border:1px solid var(--border);border-radius:8px}
table.tbl{border-collapse:collapse;width:100%;font-size:13px}
.tbl th{position:sticky;top:0;background:var(--surface-3);text-align:left;padding:8px 10px;font-weight:600;cursor:pointer;white-space:nowrap;user-select:none;z-index:1}
.tbl th:hover{color:var(--accent)}
.tbl td{padding:6px 10px;border-top:1px solid var(--border);vertical-align:top;max-width:380px;overflow-wrap:break-word}
.tbl tr:hover td{background:var(--surface-2)}
.tbl td.num,.tbl th.num{text-align:right;font-variant-numeric:tabular-nums}
.tbl tr.clickable{cursor:pointer}
.tbl-tools{display:flex;gap:8px;align-items:center;margin-bottom:8px;flex-wrap:wrap}
.tbl-tools input{width:240px}
.pager{display:flex;gap:6px;align-items:center;margin-top:8px;color:var(--text-muted);font-size:12.5px}
.badge{display:inline-block;padding:1px 8px;border-radius:20px;font-size:11.5px;background:var(--surface-3);border:1px solid var(--border);white-space:nowrap}
.badge.bad{border-color:var(--bad);color:var(--bad)}
.badge.warn{border-color:var(--warn);color:var(--warn)}
.badge.good{border-color:var(--good);color:var(--good)}
.badge.info{border-color:var(--accent);color:var(--accent)}

/* Graph */
.graph-box{position:relative;height:620px;border:1px solid var(--border);border-radius:8px;background:var(--surface-2);overflow:hidden}
.graph-box svg{width:100%;height:100%;cursor:grab;display:block}
.graph-box svg:active{cursor:grabbing}
.graph-legend{position:absolute;left:10px;bottom:10px;background:var(--surface-1);border:1px solid var(--border);border-radius:8px;padding:8px 10px;font-size:12px;display:flex;gap:12px;flex-wrap:wrap;max-width:70%}
.graph-legend span{display:inline-flex;align-items:center;gap:5px}
.graph-legend i{width:11px;height:11px;border-radius:3px;display:inline-block}
.graph-zoom{position:absolute;left:10px;top:10px;display:flex;flex-direction:column;gap:4px}
.node-label{font-size:11px;fill:var(--text-primary);pointer-events:none}
.node-sub{font-size:10px;fill:var(--text-muted);pointer-events:none}

/* Side drawer */
#drawer{position:fixed;top:56px;right:0;bottom:0;width:540px;max-width:95vw;background:var(--surface-1);border-left:1px solid var(--border);box-shadow:var(--shadow);transform:translateX(105%);transition:transform .2s;z-index:50;display:flex;flex-direction:column}
#drawer.open{transform:none}
#drawer header{display:flex;align-items:center;padding:12px 16px;border-bottom:1px solid var(--border);gap:8px}
#drawer header h3{margin:0;font-size:15px;flex:1;overflow-wrap:anywhere}
#drawer .body{overflow:auto;padding:14px 16px;flex:1}
dl.kv{display:grid;grid-template-columns:130px 1fr;gap:5px 10px;margin:0 0 12px;font-size:13px}
dl.kv dt{color:var(--text-muted)} dl.kv dd{margin:0;overflow-wrap:anywhere}

/* Modal */
#modal{position:fixed;inset:0;background:rgba(0,0,0,.55);display:flex;align-items:center;justify-content:center;z-index:80}
#modal .box{background:var(--surface-1);border:1px solid var(--border);border-radius:12px;width:min(1100px,95vw);max-height:92vh;display:flex;flex-direction:column;box-shadow:var(--shadow)}
#modal .box header{padding:14px 18px;border-bottom:1px solid var(--border);display:flex;align-items:center;gap:8px}
#modal .box header h3{margin:0;flex:1;font-size:16px}
#modal .box .body{padding:16px 18px;overflow:auto}
#modal .box footer{padding:12px 18px;border-top:1px solid var(--border);display:flex;gap:8px;justify-content:flex-end}
.map-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:10px}
.map-grid .f{display:flex;flex-direction:column;gap:4px}
.map-grid select.set{border-color:var(--good)}

.drop{border:2px dashed var(--border);border-radius:10px;padding:22px;text-align:center;color:var(--text-secondary);cursor:pointer;transition:.15s}
.drop:hover,.drop.over{border-color:var(--accent);background:color-mix(in srgb,var(--accent) 8%,transparent)}
.drop b{color:var(--text-primary)}

#toast{position:fixed;bottom:18px;left:50%;transform:translateX(-50%);background:var(--surface-3);border:1px solid var(--border);padding:10px 16px;border-radius:8px;box-shadow:var(--shadow);z-index:99;opacity:0;transition:opacity .2s;pointer-events:none;max-width:80vw}
#toast.show{opacity:1}

/* charts */
.chart{width:100%}
.chart text{fill:var(--text-secondary);font-size:11.5px}
.chart .axis line,.chart .axis path{stroke:var(--grid)}
.chart .gridline{stroke:var(--grid);stroke-dasharray:2 3}
.chart-tip{position:fixed;pointer-events:none;background:var(--surface-3);border:1px solid var(--border);border-radius:6px;padding:6px 9px;font-size:12px;z-index:90;box-shadow:var(--shadow);display:none}

.note{border-left:3px solid var(--accent);background:var(--surface-2);padding:10px 12px;border-radius:6px;margin:6px 0 12px;font-size:13px;color:var(--text-secondary)}
.note.warn{border-left-color:var(--warn)}
.list-item{display:flex;gap:10px;align-items:flex-start;padding:10px;border:1px solid var(--border);border-radius:8px;margin-bottom:8px;background:var(--surface-2)}
.list-item .grow{min-width:0}
.pill-group{display:inline-flex;border:1px solid var(--border);border-radius:8px;overflow:hidden}
.pill-group button{background:transparent;border:0;padding:6px 11px;cursor:pointer;color:var(--text-secondary)}
.pill-group button.active{background:var(--accent);color:#fff}
.hl{background:color-mix(in srgb,var(--accent-2) 35%,transparent);border-radius:3px;padding:0 2px}

@media print{
  #sidebar,#topbar,.tbl-tools,.pager,.btn,.tabs{display:none!important}
  #app{display:block} #main{overflow:visible}
}

.tbl td .mono{white-space:nowrap}

.graph-box svg path.hl-run{stroke-dasharray:12 7;animation:flowrun .7s linear infinite}
@keyframes flowrun{to{stroke-dashoffset:-19}}
.graph-box .hl-lbl{transition:opacity .3s}
.graph-box svg.live .edges path{stroke-dasharray:9 7;animation:flowrun 1.1s linear infinite}
.graph-box svg.live .edges path.hl-run{stroke-dasharray:12 7;animation-duration:.6s}
.graph-zoom .btn{justify-content:center;min-width:34px}
#drawer .tbl{font-size:12.5px} #drawer .tbl td.num{white-space:nowrap}

/* ===== v2 look ===== */
#topbar{background:linear-gradient(90deg,color-mix(in srgb,var(--accent) 16%,var(--surface-1)),var(--surface-1) 45%);backdrop-filter:blur(6px)}
#topbar .brand{letter-spacing:.6px}
#topbar .brand small{display:block;font-size:10.5px;font-weight:500;color:var(--text-muted);letter-spacing:.3px}
#sidebar{background:linear-gradient(180deg,var(--surface-1),color-mix(in srgb,var(--accent) 6%,var(--surface-1)))}
.nav-item{padding:11px 12px;font-size:14.5px;transition:background .15s}
.nav-item .num{width:26px;height:26px;border-radius:8px;font-size:13px}
.nav-item.hero{background:color-mix(in srgb,var(--accent-2) 14%,transparent);color:var(--text-primary);font-weight:600}
.nav-item.hero .num{background:var(--accent-2);color:#fff}
.nav-item.hero.active{background:color-mix(in srgb,var(--accent-2) 26%,transparent)}
.card{box-shadow:var(--shadow);border-radius:var(--radius)}
.card h3{font-size:16px}
.page-title{align-items:flex-start}
.page-title h2{font-size:23px;letter-spacing:.2px}
.sub2{color:var(--text-muted);font-size:13px;margin-top:3px}
.kpi{position:relative;overflow:hidden;box-shadow:var(--shadow);border-radius:var(--radius);padding:15px 16px 14px 20px}
.kpi::before{content:"";position:absolute;left:0;top:0;bottom:0;width:4px;background:var(--kc,var(--accent))}
.kpi .value{font-size:25px}
.kpi.c2{--kc:var(--accent-2)} .kpi.c3{--kc:var(--good)} .kpi.c4{--kc:var(--warn)} .kpi.c5{--kc:var(--bad)} .kpi.c6{--kc:var(--s7)}
.kpis-sm .kpi .value{font-size:19px}
.btn{border-radius:9px}
.btn.primary{box-shadow:0 4px 14px color-mix(in srgb,var(--accent) 35%,transparent)}
.tab.active{border-bottom-width:3px}

/* workflow steps on dashboard */
.steps{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:12px;margin-bottom:16px}
.step{background:var(--surface-1);border:1px solid var(--border);border-radius:var(--radius);padding:14px 16px;cursor:pointer;box-shadow:var(--shadow);transition:transform .12s,border-color .12s;display:flex;gap:12px;align-items:flex-start}
.step:hover{transform:translateY(-2px);border-color:var(--accent)}
.step .n{flex:none;width:34px;height:34px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:700;background:var(--surface-3)}
.step.done .n{background:var(--good);color:#fff}
.step.next .n{background:var(--accent);color:#fff}
.step b{display:block;font-size:14.5px}
.step span{font-size:12.5px;color:var(--text-muted)}
.hero-card{background:linear-gradient(120deg,color-mix(in srgb,var(--accent) 22%,var(--surface-1)),var(--surface-1) 60%);border:1px solid var(--border);border-radius:var(--radius);padding:20px 22px;margin-bottom:16px;box-shadow:var(--shadow);display:flex;gap:16px;align-items:center;flex-wrap:wrap}
.hero-card h2{margin:0;font-size:22px}

/* ===== Money Trail screen ===== */
.trail-layout{display:grid;grid-template-columns:260px 1fr;gap:16px;align-items:start}
.trail-list{position:sticky;top:0;max-height:calc(100vh - 150px);overflow:auto;padding:12px}
.cmp{padding:10px 11px;border:1px solid var(--border);border-radius:10px;margin-bottom:7px;cursor:pointer;background:var(--surface-2);transition:border-color .12s}
.cmp:hover{border-color:var(--accent)}
.cmp.active{border-color:var(--accent);background:color-mix(in srgb,var(--accent) 14%,var(--surface-2));box-shadow:inset 3px 0 0 var(--accent)}
.trail-main{min-width:0}
.trail-scroll{overflow:auto;border:1px solid var(--border);border-radius:var(--radius);background:var(--surface-2);max-height:calc(100vh - 290px);min-height:420px}
.trail-canvas{position:relative;display:flex;gap:110px;padding:16px 70px 30px 22px;width:max-content;min-width:100%}
.tsvg{position:absolute;left:0;top:0;pointer-events:none;overflow:visible}
.tsvg .tl1{font-size:11.5px;font-weight:700;fill:var(--text-primary);paint-order:stroke;stroke:var(--surface-2);stroke-width:4px}
.tsvg .tl2{font-size:10.5px;fill:var(--accent);paint-order:stroke;stroke:var(--surface-2);stroke-width:4px}
.tcol{display:flex;flex-direction:column;gap:14px;width:230px;position:relative;z-index:1}
.tcol-h{position:sticky;top:0;z-index:2;background:var(--surface-1);border:1px solid var(--border);border-radius:20px;padding:6px 12px;font-weight:700;display:flex;justify-content:space-between;align-items:center;font-size:13.5px;box-shadow:var(--shadow)}
.tcol-h span{font-weight:500;font-size:11.5px;color:var(--text-muted)}
.tcard{background:var(--surface-1);border:1px solid var(--border);border-left:4px solid var(--accent);border-radius:11px;padding:9px 11px;cursor:pointer;box-shadow:var(--shadow);transition:opacity .2s,transform .12s,border-color .12s}
.tcard:hover{transform:translateY(-1px)}
.tcard.victim{border-left-color:var(--accent-2)} .tcard.cash{border-left-color:var(--warn)} .tcard.hold{border-left-color:var(--good)} .tcard.risk{border-left-color:var(--bad)}
.tacc{font-weight:700;font-size:13px}
.tname{font-size:12.5px;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tbank{font-size:11.5px;color:var(--text-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tamt{font-weight:700;margin:4px 0 5px;font-size:14px}
.tag{display:inline-block;font-size:11px;padding:1px 8px;border-radius:12px;border:1px solid var(--border);color:var(--text-secondary)}
.tag.good{border-color:var(--good);color:var(--good)} .tag.warn{border-color:var(--warn);color:var(--warn)} .tag.bad{border-color:var(--bad);color:var(--bad)}
.trail-canvas.focus .tcard:not(.on){opacity:.22}
.trail-canvas.focus .tcard.on{box-shadow:0 0 0 2px var(--accent-2),var(--shadow)}
.trail-canvas.focus .tlink:not(.on){opacity:.1}
.tlink.on path{stroke:var(--accent-2);stroke-opacity:1;stroke-dasharray:12 7;animation:flowrun .7s linear infinite}
@media print{
  body.print-trail #sidebar,body.print-trail #topbar,body.print-trail .trail-list,body.print-trail .page-title .btn{display:none!important}
  body.print-trail .trail-layout{display:block} body.print-trail .trail-scroll{max-height:none;overflow:visible;border:0}
  body.print-trail #main{overflow:visible;padding:0}
}

.kpis-sm{grid-template-columns:repeat(5,minmax(0,1fr));gap:10px}
.kpis-sm .kpi{padding:11px 12px 10px 16px}
@media (max-width:1300px){.kpis-sm{grid-template-columns:repeat(3,minmax(0,1fr))}}
.tcol{width:215px}
.trail-canvas{gap:100px}

/* ===================== v3 – professional look ===================== */
:root{
  --bg:#0b1220; --surface-1:#101a2c; --surface-2:#0e1626; --surface-3:#18243a;
  --border:#22314b; --border-2:#2c3d5c; --text-primary:#e8edf5; --text-secondary:#a9b5c9; --text-muted:#7a879d;
  --accent:#3b82f6; --radius:10px; --shadow:0 1px 2px rgba(0,0,0,.25);
}
:root[data-theme="light"]{
  --bg:#f3f5f9; --surface-1:#ffffff; --surface-2:#f7f9fc; --surface-3:#eef2f7;
  --border:#dde3ec; --border-2:#cfd7e3; --text-primary:#111827; --text-secondary:#4b5563; --text-muted:#6b7280;
  --accent:#2563eb; --shadow:0 1px 2px rgba(16,24,40,.06);
}
html,body{font-size:13.5px}
.ico{flex:none;display:block}

/* frame */
#app{grid-template-columns:236px 1fr;grid-template-rows:52px 1fr 28px}
#topbar{background:var(--surface-1);backdrop-filter:none;border-bottom:1px solid var(--border);gap:10px;padding:0 14px}
#topbar .brand{font-size:15.5px;letter-spacing:.3px;min-width:214px}
#topbar .brand svg{width:28px;height:28px}
#topbar .brand small{font-size:10px;text-transform:uppercase;letter-spacing:.9px}
#topbar label{color:var(--text-muted);font-size:11px;text-transform:uppercase;letter-spacing:.8px}
#topbar select{height:32px;padding:4px 10px;font-weight:600;min-width:180px}
.gsearch{position:relative;display:flex;align-items:center}
.gsearch .ico{position:absolute;left:10px;color:var(--text-muted);pointer-events:none}
.gsearch input{width:330px;height:32px;padding-left:32px;border-radius:8px}
#btnTheme,#btnLock{height:32px}
#sidebar{background:var(--surface-1);padding:10px 10px 12px;display:flex;flex-direction:column}
.nav-group{font-size:10.5px;font-weight:700;letter-spacing:1.1px;text-transform:uppercase;color:var(--text-muted);padding:14px 10px 6px}
.nav-group:first-child{padding-top:4px}
.nav-item,.nav-item.hero{background:transparent;font-size:13.5px;font-weight:500;padding:8px 10px;border-radius:7px;margin-bottom:2px;gap:11px;color:var(--text-secondary);position:relative}
.nav-item .ico{color:var(--text-muted)}
.nav-item:hover{background:var(--surface-3);color:var(--text-primary)}
.nav-item.active,.nav-item.hero.active{background:color-mix(in srgb,var(--accent) 14%,transparent);color:var(--text-primary);font-weight:600}
.nav-item.active .ico{color:var(--accent)}
.nav-item.active::before{content:"";position:absolute;left:-10px;top:6px;bottom:6px;width:3px;border-radius:0 3px 3px 0;background:var(--accent)}
.nav-bottom{margin-top:auto;border-top:1px solid var(--border);padding-top:8px}
.side-note{border:1px solid var(--border);border-radius:8px;padding:10px 11px;margin-top:10px;background:var(--surface-2)}
.si-case{font-weight:700;color:var(--text-primary);margin-bottom:6px;font-size:12.5px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.si-row{display:flex;justify-content:space-between;font-size:11.5px;padding:2px 0}
.si-row b{color:var(--text-primary);font-variant-numeric:tabular-nums}
#statusbar{grid-column:1/3;display:flex;align-items:center;gap:10px;padding:0 14px;font-size:11.5px;color:var(--text-muted);background:var(--surface-1);border-top:1px solid var(--border);white-space:nowrap;overflow:hidden}
#statusbar b{color:var(--text-secondary);font-weight:600}
#statusbar .sep{opacity:.4}
#statusbar .dot{width:7px;height:7px;border-radius:50%;background:var(--good);flex:none}
#main{padding:20px 26px 40px;background:var(--bg)}
#drawer{top:52px;bottom:28px}

/* page header */
.page-head{display:flex;align-items:flex-end;gap:16px;margin:0 0 12px}
.ph-text{flex:1;min-width:0}
.crumb{font-size:11px;text-transform:uppercase;letter-spacing:1px;color:var(--text-muted);font-weight:600}
.crumb span{margin:0 4px;opacity:.6}
.page-head h2,.page-title h2{margin:3px 0 0;font-size:21px;font-weight:700;letter-spacing:.1px}
.ph-desc{color:var(--text-muted);font-size:12.5px;margin-top:3px}
.ph-actions{display:flex;gap:8px;flex-wrap:wrap}
.tabs{gap:2px;margin-bottom:18px;border-bottom:1px solid var(--border)}
.tab{padding:9px 13px;font-size:13px;font-weight:500;display:flex;align-items:center;gap:6px;border-radius:6px 6px 0 0}
.tab:hover{background:var(--surface-3)}
.tab.active{border-bottom-width:2px;color:var(--accent);font-weight:600}
.tcount{font-size:10.5px;padding:0 6px;border-radius:9px;background:var(--surface-3);color:var(--text-secondary);font-weight:600}
.tab.active .tcount{background:color-mix(in srgb,var(--accent) 20%,transparent);color:var(--accent)}

/* surfaces */
.card,.kpi,.step,.hero-card,.tcard,.tcol-h{box-shadow:var(--shadow)}
.card{border-radius:var(--radius);padding:16px 18px}
.card h3{font-size:14.5px;font-weight:650;letter-spacing:.1px}
.card .sub{font-size:12px}
.hero-card{background:var(--surface-1);border-left:3px solid var(--accent)}
.kpi{border-radius:var(--radius);padding:12px 14px 12px 16px}
.kpi::before{width:3px}
.kpi .label{font-size:11px;text-transform:uppercase;letter-spacing:.7px;font-weight:600;color:var(--text-muted)}
.kpi .value{font-size:22px;font-weight:700;font-variant-numeric:tabular-nums;margin-top:6px}
.kpi .hint{font-size:11px}
.note{border-radius:8px;font-size:12.5px}
.btn{border-radius:7px;font-weight:500}
.btn.primary{box-shadow:none;font-weight:600}
.btn.primary:hover{filter:brightness(1.08)}
.btn:not(.primary):not(.danger){background:var(--surface-1);border-color:var(--border-2)}
.btn:not(.primary):not(.danger):hover{border-color:var(--accent);color:var(--accent)}
.pill-group{border-color:var(--border-2);border-radius:7px}
.pill-group button{font-size:12.5px;font-weight:500}
input,select,textarea{border-radius:7px;background:var(--surface-2)}
.badge{font-weight:600;font-size:11px}

/* tables */
.tbl-wrap{border-radius:8px}
table.tbl{font-size:12.5px}
.tbl th{background:var(--surface-3);font-size:11px;text-transform:uppercase;letter-spacing:.6px;color:var(--text-secondary);padding:9px 10px;border-bottom:1px solid var(--border-2)}
.tbl td{padding:7px 10px}
.tbl tbody tr:nth-child(even) td{background:color-mix(in srgb,var(--surface-3) 35%,transparent)}
.tbl tr:hover td,.tbl tbody tr:nth-child(even):hover td{background:color-mix(in srgb,var(--accent) 9%,transparent)}
.tbl td.num{font-variant-numeric:tabular-nums;white-space:nowrap}
.tbl-tools input[type=search]{width:260px}

/* graphs */
.graph-box{border-radius:8px;background:var(--surface-2)}
.graph-legend{font-size:11.5px;border-radius:7px}

@media print{#statusbar{display:none!important}}
.kpis-c{grid-template-columns:repeat(auto-fit,minmax(118px,1fr));gap:10px}
.kpis-c .kpi{padding:10px 11px 10px 14px}
.kpis-c .kpi .value{font-size:18px}
.kpis-c .kpi .label{font-size:10px;letter-spacing:.5px;min-height:26px}
.filter-bar{padding:10px 14px;border-left:3px solid var(--accent)}

/* Money Trail page: live, clickable lines */
.tsvg .th{pointer-events:stroke;cursor:pointer}
.tsvg .tl1,.tsvg .tl2{pointer-events:none;opacity:0;transition:opacity .15s}
.trail-canvas.few .tsvg .tl1,.trail-canvas.few .tsvg .tl2,.tlink.on .tl1,.tlink.on .tl2,.tlink.hov .tl1,.tlink.hov .tl2{opacity:1}
.tlink.hov .tl1{font-size:13px}
.trail-canvas.live .tlink .tv{stroke-dasharray:9 7;animation:flowrun 1.2s linear infinite}
.tlink.hov .tv{stroke:var(--accent-2);stroke-opacity:1;stroke-width:5px;stroke-dasharray:12 7;animation:flowrun .6s linear infinite}
.trail-canvas.focus .tlink.hov{opacity:1}
.tlink.on .tv{stroke:var(--accent-2);stroke-opacity:1;stroke-dasharray:12 7;animation:flowrun .7s linear infinite}
.trail-canvas.focus .tcard.sel{box-shadow:0 0 0 3px var(--accent-2),var(--shadow)}

/* chart labels keep their size when zooming in */
.graph-box svg .el,.graph-box svg .nt{transform:scale(var(--iz,1));transform-box:fill-box;transform-origin:center}
.graph-box svg .nt{transform-origin:center top}
.graph-zoom [data-z="orient"]{font-size:15px}
/* coloured menu buttons */
.nav-item .nib{display:inline-flex;flex:none;width:30px;height:30px;border-radius:9px;align-items:center;justify-content:center;background:color-mix(in srgb,var(--c) 17%,transparent);border:1px solid color-mix(in srgb,var(--c) 35%,transparent);transition:background .15s,transform .15s}
.nav-item .nib .ico{color:var(--c)}
.nav-item:hover{background:color-mix(in srgb,var(--c) 10%,transparent)}
.nav-item:hover .nib{transform:scale(1.06)}
.nav-item.active,.nav-item.hero.active{background:color-mix(in srgb,var(--c) 20%,transparent);color:var(--text-primary)}
.nav-item.active .nib{background:var(--c);border-color:var(--c);box-shadow:0 4px 12px color-mix(in srgb,var(--c) 45%,transparent)}
.nav-item.active .nib .ico{color:#fff}
.nav-item.active::before{background:var(--c)}

/* coloured boxes */
.card.cc{border-top:3px solid var(--cc);background-image:linear-gradient(180deg,color-mix(in srgb,var(--cc) 10%,transparent),transparent 110px)}
.card.cc h3{color:color-mix(in srgb,var(--cc) 55%,var(--text-primary))}
.card.cc h3::before{content:"";display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--cc);margin-right:8px;vertical-align:middle;box-shadow:0 0 0 3px color-mix(in srgb,var(--cc) 25%,transparent)}

/* flagged accounts: filters and selection */
.flagbar{display:flex;flex-wrap:wrap;gap:10px 12px;align-items:flex-end;padding:12px;margin:10px 0;border:1px solid var(--border);border-radius:10px;background:var(--surface-2)}
.flagbar .f{display:flex;flex-direction:column;gap:4px;min-width:130px}
.flagbar .f.grow{flex:1;min-width:200px}
.flagbar label{font-size:11.5px;color:var(--text-muted);font-weight:600}
.flagbar input[type=number]{width:150px}
.selbar{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-bottom:8px;padding:8px 12px;border-radius:8px;background:color-mix(in srgb,var(--accent) 8%,transparent)}
.fsel{width:17px;height:17px;cursor:pointer;accent-color:var(--accent)}

.graph-legend .gcol{font-size:12px;padding:3px 8px;height:auto;margin-right:6px;font-weight:600}

/* social media sub-links and platform chips */
.nav-subs{margin:-2px 0 6px 22px;padding-left:10px;border-left:2px solid color-mix(in srgb,#ec4899 35%,transparent)}
.nav-sub{display:flex;align-items:center;gap:8px;padding:6px 10px;border-radius:7px;cursor:pointer;font-size:13px;color:var(--text-secondary);user-select:none}
.nav-sub i{width:9px;height:9px;border-radius:50%;background:var(--pc);flex:none;box-shadow:0 0 0 3px color-mix(in srgb,var(--pc) 22%,transparent)}
.nav-sub:hover{background:var(--surface-2);color:var(--text-primary)}
.nav-sub.active{background:color-mix(in srgb,var(--pc) 20%,transparent);color:var(--text-primary);font-weight:600}
.platbar{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin:4px 0 12px}
.pchip{display:inline-flex;align-items:center;gap:7px;padding:6px 12px;border-radius:999px;cursor:pointer;font-size:13px;border:1px solid color-mix(in srgb,var(--pc) 45%,var(--border));background:color-mix(in srgb,var(--pc) 8%,transparent)}
.pchip i{width:9px;height:9px;border-radius:50%;background:var(--pc)}
.pchip b{font-weight:700}
.pchip.on{background:var(--pc);color:#fff;border-color:var(--pc)}
.pchip.on i{background:#fff}

/* emblem: big on the login page, small in the top bar */
.emblem{background:url(data:image/webp;base64,) center/contain no-repeat;aspect-ratio:1/1;flex:none}
.emblem-sm{background-image:url(data:image/webp;base64,);height:40px;width:auto}

/* ===== Home / login page ===== */
#login{display:block;overflow:auto;padding:0;color:#e5e9f2;
  background:radial-gradient(900px 520px at 78% 30%,rgba(245,158,11,.13),transparent 60%),radial-gradient(1000px 600px at 10% 0%,rgba(59,130,246,.18),transparent 60%),
  linear-gradient(rgba(148,163,184,.05) 1px,transparent 1px) 0 0/44px 44px,linear-gradient(90deg,rgba(148,163,184,.05) 1px,transparent 1px) 0 0/44px 44px,#070d1a}
#login.hidden{display:none}
.hp{max-width:1280px;margin:0 auto;padding:0 clamp(18px,4vw,48px);min-height:100%;display:flex;flex-direction:column}
.hp-top{display:flex;align-items:center;gap:14px;padding:18px 0;border-bottom:1px solid rgba(148,163,184,.14)}
.hp-brand{display:flex;align-items:center;gap:11px}
.hp-brand b{display:block;font-size:19px;letter-spacing:.4px}
.hp-brand small{display:block;font-size:10.5px;text-transform:uppercase;letter-spacing:1.4px;color:#94a3b8}
.hp-spacer{flex:1}
.hp-pill{display:inline-flex;align-items:center;gap:8px;font-size:12.5px;color:#a7f3d0;padding:6px 12px;border-radius:999px;border:1px solid rgba(16,185,129,.35);background:rgba(16,185,129,.08)}
.hp-pill i{width:8px;height:8px;border-radius:50%;background:#10b981;box-shadow:0 0 0 4px rgba(16,185,129,.2)}
.hp-btn{display:inline-flex;align-items:center;gap:9px;border:0;cursor:pointer;font:600 14px/1 inherit;font-family:inherit;color:#fff;padding:11px 20px;border-radius:10px;
  background:linear-gradient(135deg,#2563eb,#1d4ed8);box-shadow:0 6px 18px rgba(37,99,235,.35),inset 0 1px 0 rgba(255,255,255,.18);transition:transform .15s,box-shadow .15s}
.hp-btn:hover{transform:translateY(-1px);box-shadow:0 10px 24px rgba(37,99,235,.45),inset 0 1px 0 rgba(255,255,255,.18)}
.hp-btn svg{width:17px;height:17px}
.hp-btn.big{font-size:16px;padding:15px 28px;border-radius:12px;background:linear-gradient(135deg,#f59e0b,#ea580c);box-shadow:0 10px 28px rgba(234,88,12,.35),inset 0 1px 0 rgba(255,255,255,.25)}
.hp-btn.big:hover{box-shadow:0 14px 34px rgba(234,88,12,.5),inset 0 1px 0 rgba(255,255,255,.25)}
.hp-ghost{color:#cbd5e1;font-weight:600;font-size:14.5px;text-decoration:none;padding:14px 8px}
.hp-ghost:hover{color:#fff}
.hp-hero{display:grid;grid-template-columns:1.25fr .75fr;align-items:center;gap:clamp(24px,4vw,64px);padding:clamp(28px,5vh,64px) 0 clamp(24px,4vh,48px)}
.hp-kicker{display:inline-block;font-size:12px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:#fbbf24;padding:6px 12px;border-radius:6px;background:rgba(245,158,11,.1);border:1px solid rgba(245,158,11,.3)}
.hp-copy h1{font-size:clamp(34px,4.2vw,54px);line-height:1.08;margin:18px 0 16px;font-weight:800;letter-spacing:-.5px;color:#f8fafc}
.hp-copy h1 span{background:linear-gradient(90deg,#fbbf24,#f97316 55%,#ef4444);-webkit-background-clip:text;background-clip:text;color:transparent}
.hp-lead{font-size:clamp(15px,1.25vw,18px);line-height:1.6;color:#b6c2d6;max-width:600px;margin:0 0 26px}
.hp-cta{display:flex;flex-wrap:wrap;align-items:center;gap:10px 18px}
.hp-trust{display:flex;flex-wrap:wrap;gap:12px;list-style:none;padding:0;margin:30px 0 0}
.hp-trust li{font-size:12.5px;color:#94a3b8;padding:10px 14px;border-radius:10px;background:rgba(15,23,42,.7);border:1px solid rgba(148,163,184,.16);min-width:150px}
.hp-trust b{display:block;color:#e2e8f0;font-size:14px;margin-bottom:2px}
.hp-art{position:relative;display:flex;justify-content:center;align-items:center}
.hp-ring{position:absolute;width:88%;aspect-ratio:1;border-radius:50%;background:radial-gradient(circle,rgba(245,158,11,.16),rgba(59,130,246,.08) 55%,transparent 70%)}
.emblem-big{position:relative;height:min(60vh,530px);max-width:100%;filter:drop-shadow(0 18px 36px rgba(0,0,0,.6));animation:emIn .6s ease-out}
@keyframes emIn{from{opacity:0;transform:scale(.94)}to{opacity:1;transform:none}}
.hp-feats{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;padding:8px 0 28px}
.hp-feat{display:flex;gap:14px;align-items:flex-start;padding:16px 18px;border-radius:14px;background:linear-gradient(180deg,rgba(17,25,43,.92),rgba(11,18,32,.92));border:1px solid rgba(148,163,184,.14);border-top:3px solid var(--fc);transition:transform .15s,border-color .15s}
.hp-feat:hover{transform:translateY(-2px);border-color:color-mix(in srgb,var(--fc) 55%,transparent)}
.hp-fi{flex:none;width:42px;height:42px;border-radius:11px;display:grid;place-items:center;color:var(--fc);background:color-mix(in srgb,var(--fc) 16%,transparent)}
.hp-fi svg{width:22px;height:22px}
.hp-feat b{font-size:15px;color:#f1f5f9}
.hp-feat p{margin:4px 0 0;font-size:13px;line-height:1.5;color:#94a3b8}
.hp-foot{margin-top:auto;padding:16px 0 22px;border-top:1px solid rgba(148,163,184,.12);font-size:12px;color:#64748b;text-align:center}
/* login box over the home page */
.lg-wrap{position:fixed;inset:0;z-index:50;display:flex;align-items:center;justify-content:center;padding:20px;background:rgba(3,7,18,.66);backdrop-filter:blur(6px);opacity:0;pointer-events:none;transition:opacity .2s}
.lg-wrap.open{opacity:1;pointer-events:auto}
.lg-wrap .login-card{position:relative;width:400px;transform:translateY(10px) scale(.98);transition:transform .2s;border-top:3px solid #f59e0b}
.lg-wrap.open .login-card{transform:none}
.lg-head{display:flex;align-items:center;gap:12px;margin-bottom:6px}
.lg-head .emblem-sm{height:54px}
.lg-head h1{margin:0;font-size:24px}
.lg-x{position:absolute;top:12px;right:12px;border:0;background:transparent;color:var(--text-muted);font-size:16px;cursor:pointer;width:30px;height:30px;border-radius:8px}
.lg-x:hover{background:var(--surface-2);color:var(--text-primary)}
@media (max-width:1000px){.hp-hero{grid-template-columns:1fr;text-align:center}.hp-lead{margin-left:auto;margin-right:auto}.hp-cta,.hp-trust{justify-content:center}.hp-art{order:-1}.emblem-big{height:min(42vh,380px)}.hp-feats{grid-template-columns:repeat(2,1fr)}.hp-pill{display:none}}
@media (max-width:620px){.hp-feats{grid-template-columns:1fr}.hp-brand small{display:none}}

/* Sudarshan Chakra: spins clockwise behind the emblem and in the header */
@keyframes chakraSpin{to{transform:rotate(360deg)}}
.chakra-big{position:absolute;width:min(78vh,700px);max-width:125%;aspect-ratio:1;animation:chakraSpin 14s linear infinite;filter:drop-shadow(0 0 22px rgba(251,191,36,.45)) drop-shadow(0 0 60px rgba(234,88,12,.25));opacity:.95}
.hp-mark{position:relative;width:64px;height:64px;flex:none;display:grid;place-items:center}
.chakra-sm{width:64px;height:64px;animation:chakraSpin 6s linear infinite;filter:drop-shadow(0 0 8px rgba(251,191,36,.55))}
.hp-brand b{background:linear-gradient(90deg,#f8fafc,#fbbf24 70%,#f97316);-webkit-background-clip:text;background-clip:text;color:transparent;font-size:21px}
.hp-by{display:inline-flex;align-items:center;gap:8px;margin-top:4px;font-size:12.5px;font-weight:600;color:#e2e8f0}
.hp-by i{font-style:normal;font-weight:500;color:#fbbf24;padding:1px 8px;border-radius:999px;background:rgba(245,158,11,.12);border:1px solid rgba(245,158,11,.3)}
.hp-top .hp-btn.big{padding:13px 22px;font-size:15px}
.hp-foot b{color:#94a3b8}
@media (max-width:1000px){.chakra-big{width:min(56vh,500px)}.hp-art{margin:50px 0}}
@media (max-width:620px){.hp-top .hp-btn.big{padding:10px 14px;font-size:13.5px}.hp-by{display:none}}
.hp-hero{padding-top:clamp(48px,9vh,96px);padding-bottom:clamp(48px,9vh,96px)}

/* home page: second button under Login to workspace */
.hp-actions{display:flex;flex-direction:column;gap:8px;align-items:stretch}
.hp-actions .hp-btn{justify-content:center}
.hp-btn2{display:inline-flex;align-items:center;justify-content:center;gap:9px;cursor:pointer;font:600 14px/1 inherit;font-family:inherit;color:#bfdbfe;padding:11px 18px;border-radius:10px;border:1px solid rgba(96,165,250,.45);background:rgba(37,99,235,.14);transition:background .15s,color .15s}
.hp-btn2:hover{background:rgba(37,99,235,.28);color:#fff}
.hp-btn2 svg{width:17px;height:17px}
/* Search in Local Drive */
.ls-wrap{position:fixed;inset:0;z-index:85;display:flex;align-items:flex-start;justify-content:center;padding:4vh 16px;background:rgba(3,7,18,.7);backdrop-filter:blur(6px);opacity:0;pointer-events:none;transition:opacity .2s;overflow:auto}
.ls-wrap.open{opacity:1;pointer-events:auto}
.ls-box{position:relative;width:min(1180px,100%);background:var(--surface-1);border:1px solid var(--border);border-top:3px solid #3b82f6;border-radius:16px;box-shadow:var(--shadow);color:var(--text-primary)}
.ls-head{display:flex;gap:12px;align-items:flex-start;padding:20px 24px 12px;border-bottom:1px solid var(--border)}
.ls-head h2{margin:0 0 4px;font-size:20px}
.ls-sub{font-size:13.5px;color:var(--text-muted)}
.ls-head .lg-x{position:static;margin-left:auto}
.ls-body{padding:16px 24px 20px}
.ls-pick{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin-bottom:12px}
.ls-pick label.btn{cursor:pointer}
.ls-q textarea{width:100%;font-size:15px;padding:10px 12px;resize:vertical;font-family:inherit}
.ls-opts{display:flex;flex-wrap:wrap;gap:8px 18px;align-items:center;margin-top:8px;font-size:13px}
.ls-opts label{display:inline-flex;gap:6px;align-items:center}
.ls-prog{display:flex;gap:12px;align-items:center;margin:12px 0}
.ls-bar{flex:none;width:260px;height:8px;border-radius:99px;background:var(--surface-3);overflow:hidden}
.ls-bar i{display:block;height:100%;width:0;background:linear-gradient(90deg,#3b82f6,#f59e0b);transition:width .15s}
.ls-sum{display:flex;flex-wrap:wrap;gap:10px;align-items:center;justify-content:space-between;margin:14px 0 8px}
.ls-chip{display:inline-block;margin:0 8px 6px 0;padding:5px 11px;border-radius:999px;font-size:13px;background:var(--surface-2);border:1px solid var(--border);color:var(--text-muted)}
.ls-chip.hit{background:color-mix(in srgb,#10b981 14%,transparent);border-color:color-mix(in srgb,#10b981 45%,transparent);color:var(--text-primary)}
.ls-warn{margin:12px 0;padding:10px 12px;border-radius:8px;background:color-mix(in srgb,#f59e0b 14%,transparent);color:var(--text-primary)}
.ls-skip{font-size:12.5px;color:var(--text-muted);max-height:160px;overflow:auto;margin-bottom:8px;padding:8px;border-radius:8px;background:var(--surface-2)}
.ls-res{max-height:56vh;overflow:auto;border-radius:10px}
.ls-tbl{width:100%;border-collapse:collapse;font-size:13px}
.ls-tbl th{position:sticky;top:0;background:var(--surface-3);text-align:left;padding:8px 10px;font-weight:600}
.ls-tbl td{padding:7px 10px;border-top:1px solid var(--border);vertical-align:top}
.ls-tbl tr:hover td{background:var(--surface-2)}
.ls-tbl mark{background:#fbbf24;color:#1f1300;border-radius:3px;padding:0 2px}
.ls-file{word-break:break-all;max-width:320px;color:var(--accent)}
.ls-tbl .nowrap{white-space:nowrap}
.ls-empty{padding:30px;text-align:center;color:var(--text-muted)}
.ls-note{margin-top:12px}

/* Social Media drop-down */
.nav-chev{margin-left:auto;width:22px;height:22px;display:grid;place-items:center;border-radius:6px;font-size:13px;transition:transform .2s,background .15s;transform:rotate(-90deg)}
.nav-chev:hover{background:color-mix(in srgb,var(--c) 30%,transparent)}
.nav-item.open .nav-chev{transform:none}
.nav-subs{max-height:0;opacity:0;overflow:hidden;margin-top:0;margin-bottom:0;transition:max-height .25s ease,opacity .2s,margin .2s}
.nav-subs.open{max-height:260px;opacity:1;margin-top:-2px;margin-bottom:6px}

/* sidebar items never squeeze: the menu scrolls instead */
#sidebar>*{flex-shrink:0}

/* Analytics: Common Suspect */
.btn.big{padding:12px 20px;font-size:15px;font-weight:700}
.cs-imp{border-top:3px solid #f97316}
.cs-stat{display:flex;flex-wrap:wrap;gap:10px;margin-top:12px}
.cs-stat span{padding:6px 12px;border-radius:999px;background:var(--surface-2);border:1px solid var(--border);font-size:13px}
.cs-fields{display:flex;flex-wrap:wrap;gap:8px;margin-top:8px}

/* CAF Analysis */
.caf-mini{width:34px;height:40px;object-fit:cover;border-radius:5px;border:1px solid var(--border);margin-right:8px;vertical-align:middle}
.caf-phs{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px}
.caf-ph{height:120px;border-radius:8px;border:1px solid var(--border)}
.caf-txt{white-space:pre-wrap;font-size:12px;max-height:40vh;overflow:auto;background:var(--surface-2);padding:10px;border-radius:8px}
.caf-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:10px;margin-top:8px}
.caf-card{display:flex;gap:10px;align-items:center;padding:8px;border-radius:10px;border:1px solid var(--border);background:var(--surface-2);cursor:pointer}
.caf-card:hover{border-color:var(--accent)}
.caf-card img{width:64px;height:76px;object-fit:cover;border-radius:6px}

/* ===== Left menu redesign: every button has its own colour ===== */
#sidebar .nav-item{position:relative;margin:0 0 6px;padding:8px 10px;border-radius:12px;font-weight:600;color:color-mix(in srgb,var(--c) 30%,var(--text-primary));
  background:linear-gradient(90deg,color-mix(in srgb,var(--c) 16%,transparent),color-mix(in srgb,var(--c) 4%,transparent));border:1px solid color-mix(in srgb,var(--c) 30%,transparent);transition:transform .15s,background .15s,box-shadow .15s}
#sidebar .nav-item .nib{background:linear-gradient(135deg,var(--c),color-mix(in srgb,var(--c) 60%,#000));border:0;box-shadow:0 3px 10px color-mix(in srgb,var(--c) 40%,transparent)}
#sidebar .nav-item .nib .ico{color:#fff}
#sidebar .nav-item:hover{transform:translateX(3px);background:linear-gradient(90deg,color-mix(in srgb,var(--c) 28%,transparent),color-mix(in srgb,var(--c) 8%,transparent));box-shadow:0 4px 14px color-mix(in srgb,var(--c) 22%,transparent)}
#sidebar .nav-item.active{color:#fff;background:linear-gradient(90deg,var(--c),color-mix(in srgb,var(--c) 55%,#0b1220));border-color:var(--c);box-shadow:0 6px 18px color-mix(in srgb,var(--c) 40%,transparent)}
#sidebar .nav-item.active .nib{background:rgba(255,255,255,.22);box-shadow:none}
#sidebar .nav-item.active::before{display:none}
#sidebar .nav-item[data-page="osint"]::after{content:"↗";margin-left:auto;font-size:13px;opacity:.75}

/* ===== Search in Local Drive v2 ===== */
.ls-box{border-top:4px solid #6366f1}
.ls-head{align-items:center}
.ls-hico{width:46px;height:46px;border-radius:12px;display:grid;place-items:center;font-size:22px;background:linear-gradient(135deg,#6366f1,#3b82f6);box-shadow:0 6px 16px rgba(99,102,241,.35);flex:none}
.ls-step{display:flex;gap:14px;padding:14px 0;border-bottom:1px dashed var(--border)}
.ls-num{flex:none;width:30px;height:30px;border-radius:50%;display:grid;place-items:center;font-weight:800;color:#fff;background:linear-gradient(135deg,#6366f1,#8b5cf6)}
.ls-sec{flex:1;min-width:0}
.ls-t{font-weight:700;font-size:15px;margin:4px 0 10px}
.ls-drop{display:flex;flex-wrap:wrap;gap:10px;align-items:center;padding:14px;border:2px dashed color-mix(in srgb,#6366f1 45%,var(--border));border-radius:12px;background:color-mix(in srgb,#6366f1 6%,transparent);transition:background .15s}
.ls-drop.over{background:color-mix(in srgb,#6366f1 18%,transparent)}
.ls-srcs{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-top:10px}
.ls-src{display:inline-flex;align-items:center;gap:6px;padding:6px 6px 6px 12px;border-radius:999px;background:var(--surface-2);border:1px solid var(--border);font-size:13px}
.ls-src button{border:0;background:transparent;color:var(--text-muted);cursor:pointer;width:22px;height:22px;border-radius:50%}
.ls-src button:hover{background:var(--surface-3);color:var(--bad)}
.ls-help{margin-top:10px;font-size:13px;color:var(--text-secondary)}
.ls-help summary{cursor:pointer;color:var(--accent);font-weight:600}
.ls-help div{margin-top:6px;line-height:1.7;padding:10px 12px;border-radius:8px;background:var(--surface-2)}
.ls-chips{display:flex;flex-wrap:wrap;gap:8px}
.ls-chip{margin:0;padding:7px 13px;border-radius:999px;font-size:13px;cursor:pointer;background:var(--surface-2);border:1px solid var(--border);color:var(--text-muted);font-family:inherit}
.ls-chip.on{background:color-mix(in srgb,#10b981 16%,transparent);border-color:color-mix(in srgb,#10b981 55%,transparent);color:var(--text-primary);font-weight:600}
.ls-chip.on::before{content:"✓ "}
.ls-modes{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:12px}
.ls-mode{text-align:left;padding:12px 14px;border-radius:12px;cursor:pointer;background:var(--surface-2);border:2px solid var(--border);color:var(--text-primary);font-family:inherit}
.ls-mode b{display:block;font-size:14.5px;margin-bottom:3px}
.ls-mode span{font-size:12.5px;color:var(--text-muted)}
.ls-mode.on{border-color:#6366f1;background:color-mix(in srgb,#6366f1 12%,transparent)}
.ls-findrow{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin-bottom:8px;font-size:13px}
.ls-go{display:flex;flex-wrap:wrap;gap:12px;align-items:center;margin-top:14px}
.ls-prog{flex-direction:column;align-items:stretch;gap:6px;padding:12px 14px;border-radius:10px;background:var(--surface-2);margin-top:14px}
.ls-prog .ls-bar{width:100%}
.ls-cur{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ls-pill{display:inline-block;margin:0 8px 6px 0;padding:5px 11px;border-radius:999px;font-size:13px;background:var(--surface-2);border:1px solid var(--border);color:var(--text-muted)}
.ls-pill.hit{background:color-mix(in srgb,#10b981 14%,transparent);border-color:color-mix(in srgb,#10b981 45%,transparent);color:var(--text-primary)}
.ls-detail{margin-top:14px;padding:12px;border-radius:12px;border:1px solid color-mix(in srgb,#6366f1 45%,var(--border));background:color-mix(in srgb,#6366f1 6%,transparent)}
.ls-detail h3{margin:0;font-size:15px}
.ls-res .tbl-wrap{max-height:56vh}
@media (max-width:760px){.ls-modes{grid-template-columns:1fr}}

/* CAF import box, photo captions, edit form */
.caf-drop{display:flex;align-items:center;gap:14px;padding:16px 18px;margin-bottom:14px;border:2px dashed color-mix(in srgb,#84cc16 55%,var(--border));border-radius:14px;background:color-mix(in srgb,#84cc16 8%,var(--surface))}
.caf-drop.over{background:color-mix(in srgb,#84cc16 20%,var(--surface));border-style:solid}
.caf-drop-ic{font-size:30px}
.caf-fig{margin:0;text-align:center}.caf-fig figcaption{font-size:11px;color:var(--text-muted,#888);margin-top:3px}
.caf-ph{cursor:zoom-in}.caf-ph.scan{height:160px}
.caf-edit{display:grid;grid-template-columns:1fr 1fr;gap:8px}.caf-edit label{display:flex;flex-direction:column;font-size:12px;gap:3px}.caf-edit input{width:100%}

/* Home page trust boxes: each its own colour */
.hp-trust{gap:14px}
.hp-trust li{--c:#10b981;display:flex;align-items:center;gap:11px;min-width:0;padding:11px 15px 11px 11px;border-radius:14px;color:#cbd5e1;
  background:linear-gradient(135deg,color-mix(in srgb,var(--c) 22%,rgba(15,23,42,.9)),rgba(15,23,42,.85) 70%);
  border:1px solid color-mix(in srgb,var(--c) 45%,transparent);box-shadow:0 8px 24px -10px color-mix(in srgb,var(--c) 60%,transparent),inset 0 1px 0 rgba(255,255,255,.06);transition:transform .2s,box-shadow .2s}
.hp-trust li:hover{transform:translateY(-3px);box-shadow:0 14px 30px -10px color-mix(in srgb,var(--c) 75%,transparent)}
.hp-trust li.t-off{--c:#10b981}.hp-trust li.t-pri{--c:#3b82f6}.hp-trust li.t-lock{--c:#f59e0b}
.hp-trust li i{flex:0 0 auto;width:40px;height:40px;border-radius:11px;display:grid;place-items:center;background:linear-gradient(135deg,var(--c),color-mix(in srgb,var(--c) 55%,#000));box-shadow:0 4px 12px color-mix(in srgb,var(--c) 50%,transparent)}
.hp-trust li i svg{width:22px;height:22px;fill:none;stroke:#fff;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.hp-trust li span{display:block;text-align:left;line-height:1.35}
.hp-trust li b{color:color-mix(in srgb,var(--c) 35%,#fff);font-size:15px;letter-spacing:.2px}

/* Local search: C: / D: drive check boxes */
.ls-drives{display:flex;flex-wrap:wrap;align-items:center;gap:10px;margin:2px 0 12px}
.ls-dl{font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:.6px;color:var(--text-muted,#94a3b8);margin-right:4px}
.ls-drv{--c:#3b82f6;position:relative;display:flex;align-items:center;gap:10px;padding:10px 14px 10px 10px;border-radius:12px;cursor:pointer;user-select:none;
  border:1.5px solid color-mix(in srgb,var(--c) 35%,var(--border));background:color-mix(in srgb,var(--c) 7%,var(--surface));transition:all .15s;min-width:190px}
.ls-drv[data-dlab="D"]{--c:#10b981}.ls-drv[data-dlab="both"]{--c:#a855f7}
.ls-drv:hover{border-color:var(--c)}
.ls-drv.on{border-color:var(--c);background:color-mix(in srgb,var(--c) 18%,var(--surface));box-shadow:0 4px 16px -6px color-mix(in srgb,var(--c) 70%,transparent)}
.ls-drv input{position:absolute;opacity:0;pointer-events:none}
.ls-dbox{width:20px;height:20px;border-radius:6px;border:2px solid color-mix(in srgb,var(--c) 70%,var(--border));display:grid;place-items:center;flex:0 0 auto;background:var(--surface)}
.ls-drv.on .ls-dbox{background:var(--c);border-color:var(--c)}
.ls-drv.on .ls-dbox::after{content:"✓";color:#fff;font-size:13px;font-weight:800;line-height:1}
.ls-drv input:focus-visible+.ls-dbox{outline:2px solid var(--c);outline-offset:2px}
.ls-dic{font-size:20px}
.ls-drv b{display:block;font-size:14px}.ls-drv small{display:block;font-size:11.5px;color:var(--text-muted,#94a3b8)}
.ls-dpanel{font-size:13px;padding:10px 12px;margin:0 0 10px;border-radius:10px;border:1px solid var(--border);background:var(--surface-2)}
.ls-dpanel[data-dpC]{border-left:3px solid #3b82f6}.ls-dpanel[data-dpD]{border-left:3px solid #10b981}
.ls-cparts{display:flex;flex-wrap:wrap;gap:8px;margin-top:8px}
.ls-cpart{display:flex;align-items:center;gap:6px;padding:6px 10px;border-radius:9px;border:1px solid var(--border);background:var(--surface);cursor:pointer;font-size:13px}
.ls-cpart.on{border-color:#3b82f6;background:color-mix(in srgb,#3b82f6 16%,var(--surface))}

/* Notice drafts */
.nt-grid{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:14px;align-items:start}
@media (max-width:1100px){.nt-grid{grid-template-columns:1fr}}
.nt-form{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.nt-form label{display:flex;flex-direction:column;gap:4px;font-size:12px;color:var(--text-muted,#94a3b8)}
.nt-form .nt-wide{grid-column:1/-1}.nt-form select,.nt-form input{width:100%}
.nt-ed .nt-name{width:100%;font-weight:600;font-size:14px;margin:6px 0 8px}
.nt-ed textarea{width:100%;min-height:460px;font-family:Georgia,'Times New Roman',serif;font-size:14px;line-height:1.55;background:#fffdf8;color:#1f2937;border-radius:10px;padding:16px 18px}
.nt-btns{margin-top:10px;flex-wrap:wrap;gap:8px}
.nt-list{position:sticky;top:10px;max-height:calc(100vh - 140px);overflow:auto}
.nt-item{display:flex;gap:8px;align-items:flex-start;padding:9px 10px;border-radius:10px;border:1px solid var(--border);margin-bottom:8px;cursor:pointer;background:var(--surface-2)}
.nt-item:hover{border-color:var(--accent)}.nt-item.on{border-color:#eab308;background:color-mix(in srgb,#eab308 12%,var(--surface-2))}
.nt-acts{display:flex;gap:4px}
/* Report card */
.rp-hero{display:flex;gap:16px;align-items:flex-start;border:1px solid color-mix(in srgb,#2563eb 40%,var(--border));background:linear-gradient(135deg,color-mix(in srgb,#2563eb 14%,var(--surface)),var(--surface) 70%)}
.rp-ic{font-size:40px;line-height:1}.rp-hero .btn.big{padding:11px 18px;font-size:14px}
.rp-hero .rp-pdf{background:linear-gradient(135deg,#dc2626,#991b1b);border-color:#b91c1c}

/* ===== Charts: colourful bars + donut, pop-out on hover, big live tooltip ===== */
.ch-host{position:relative}
.ch-sw{display:inline-flex;gap:2px;padding:3px;border-radius:10px;background:var(--surface-3);border:1px solid var(--border);margin:0 0 8px;float:right;position:relative;z-index:1}
.ch-sw button{border:0;background:transparent;color:var(--text-muted,#94a3b8);font-size:11.5px;font-weight:600;padding:4px 9px;border-radius:7px;cursor:pointer}
.ch-sw button:hover{color:var(--text-primary)}
.ch-sw button.on{background:linear-gradient(135deg,#3b82f6,#8b5cf6);color:#fff;box-shadow:0 2px 8px rgba(99,102,241,.4)}
.ch-body{clear:both}
.ch-both{display:grid;grid-template-columns:minmax(0,2fr) minmax(0,3fr);gap:12px;align-items:center}
.ch-bw{min-width:0}.ch-bw>svg{width:100%;height:auto;display:block}
.ch-dwrap{display:flex;align-items:center;gap:14px}
.ch-dwrap>svg{flex:0 0 auto;width:min(260px,48%);height:auto}
.ch-both .ch-dwrap>svg{width:100%;max-width:240px;margin:auto}
.ch-leg{flex:1;display:flex;flex-direction:column;gap:3px;max-height:260px;overflow:auto;font-size:12px}
.lg-it{display:flex;align-items:center;gap:7px;padding:3px 7px;border-radius:7px;cursor:default;transition:background .15s,transform .15s}
.lg-it i{width:11px;height:11px;border-radius:3px;flex:0 0 auto}
.lg-it .t{flex:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.lg-it.on,.lg-it:hover{background:var(--surface-3);transform:translateX(3px)}
svg.c2 text{font-size:11px;fill:var(--text-muted,#94a3b8)}
svg.c2 .lb{fill:var(--text-primary);font-size:11.5px}
svg.c2 .vl{fill:var(--text-primary);font-weight:700;font-size:11px}
svg.c2 .vt{fill:var(--text-primary);font-weight:700;font-size:10px}
svg.c2 .it{transition:opacity .2s}
svg.c2 .bar{transition:transform .22s cubic-bezier(.3,1.6,.5,1),filter .2s;transform-box:fill-box}
svg.c2.hb .bar{transform-origin:left center}
svg.c2.vb .bar{transform-origin:center bottom}
svg.c2.hov .it:not(.pop){opacity:.38}
svg.c2.hb .it.pop .bar{transform:scale(1.06,1.45);filter:drop-shadow(0 0 7px var(--c)) brightness(1.15)}
svg.c2.vb .it.pop .bar{transform:scale(1.22,1.06);filter:drop-shadow(0 0 8px var(--c)) brightness(1.15)}
svg.c2 .it.pop .lb,svg.c2 .it.pop .vl,svg.c2 .it.pop .vt{fill:var(--c);font-weight:800}
svg.c2 .it.pop .vl{font-size:13px}
svg.c2.dn .sl path{transition:transform .22s cubic-bezier(.3,1.6,.5,1),filter .2s;transform-box:view-box;transform-origin:center}
svg.c2.dn .sl.pop path{transform:translate(var(--dx),var(--dy)) scale(1.07);filter:drop-shadow(0 0 8px var(--c)) brightness(1.12)}
svg.c2.dn .dn-c1{font-size:12px;fill:var(--text-muted,#94a3b8);font-weight:600}
svg.c2.dn .dn-c2{font-size:20px;fill:var(--text-primary);font-weight:800}
svg.c2.ln .guide{stroke:var(--c);stroke-dasharray:3 3;opacity:0;transition:opacity .15s}
svg.c2.ln .dot{transition:r .2s,filter .2s}
svg.c2.ln .dot.hid{opacity:0}
svg.c2.ln .it.pop .guide{opacity:.8}
svg.c2.ln .it.pop .dot{r:8;opacity:1;filter:drop-shadow(0 0 7px var(--c))}
svg.c2.ln.hov .it:not(.pop){opacity:1}
.chart-tip{transition:opacity .15s,transform .15s;opacity:0;transform:scale(.92);transform-origin:top left;min-width:180px;max-width:300px;padding:11px 14px!important;border-radius:12px!important;
  background:linear-gradient(160deg,rgba(30,41,59,.97),rgba(15,23,42,.97))!important;border:1px solid rgba(148,163,184,.3)!important;box-shadow:0 18px 40px -8px rgba(0,0,0,.6)!important;color:#e2e8f0!important;pointer-events:none}
.chart-tip.on{opacity:1;transform:scale(1)}
.chart-tip .ct-h{display:flex;align-items:center;gap:8px;font-size:13px;font-weight:600;color:#cbd5e1}
.chart-tip .ct-h i{width:12px;height:12px;border-radius:4px;flex:0 0 auto}
.chart-tip .ct-v{font-size:22px;font-weight:800;color:#fff;margin:4px 0 6px;letter-spacing:.2px}
.chart-tip .ct-p{height:6px;border-radius:4px;background:rgba(148,163,184,.25);overflow:hidden}.chart-tip .ct-p span{display:block;height:100%;border-radius:4px}
.chart-tip .ct-s{font-size:11.5px;color:#94a3b8;margin-top:4px}
.ch-empty{padding:26px 0;text-align:center}
@media (max-width:700px){.ch-both{grid-template-columns:1fr}}

/* ===== Every box and button in its own colour ===== */
.card.cc{border:1px solid color-mix(in srgb,var(--cc) 32%,var(--border));border-top:3px solid var(--cc);
  background-image:linear-gradient(160deg,color-mix(in srgb,var(--cc) 13%,transparent),transparent 55%);transition:box-shadow .2s,border-color .2s}
.card.cc:hover{border-color:color-mix(in srgb,var(--cc) 60%,var(--border));box-shadow:0 10px 30px -12px color-mix(in srgb,var(--cc) 55%,transparent)}
.kpi.kc2{border:1px solid color-mix(in srgb,var(--kc) 35%,var(--border));background:linear-gradient(150deg,color-mix(in srgb,var(--kc) 20%,var(--surface-1)),var(--surface-1) 70%);transition:transform .2s,box-shadow .2s}
