.kpi.kc2 .value{color:color-mix(in srgb,var(--kc) 22%,#fff)}
.step.kc2{--kc:#3b82f6;border-color:color-mix(in srgb,var(--kc) 40%,var(--border));background:linear-gradient(150deg,color-mix(in srgb,var(--kc) 18%,var(--surface-1)),var(--surface-1) 70%)}
.step.kc2 .n{background:color-mix(in srgb,var(--kc) 35%,var(--surface-3));color:#fff}
.step.kc2.done .n{background:var(--kc)}
.step.kc2:hover{border-color:var(--kc);box-shadow:0 10px 24px -12px color-mix(in srgb,var(--kc) 70%,transparent)}
#main .btn.bc:not(.danger){--bc:#3b82f6;background:color-mix(in srgb,var(--bc) 16%,var(--surface-3));border-color:color-mix(in srgb,var(--bc) 50%,var(--border));color:color-mix(in srgb,var(--bc) 35%,var(--text-primary));transition:all .15s}
#main .btn.bc:not(.danger):hover{background:color-mix(in srgb,var(--bc) 30%,var(--surface-3));border-color:var(--bc);transform:translateY(-1px);box-shadow:0 6px 16px -8px var(--bc)}
#main .btn.bc.primary:not(.danger){background:linear-gradient(135deg,var(--bc),color-mix(in srgb,var(--bc) 62%,#000));border-color:var(--bc);color:#fff;box-shadow:0 4px 14px color-mix(in srgb,var(--bc) 40%,transparent)}
.tabs .tab.active{border-bottom-color:var(--tc,var(--accent));color:var(--tc,var(--accent))}

/* At a glance chart card */
