/* restricted access: one compact, bold strip */
.rx-note{display:flex;align-items:center;gap:14px;margin:14px 0 6px;padding:8px 18px 8px 8px;border-radius:999px;
  background:linear-gradient(90deg,rgba(220,38,38,.22),rgba(17,24,39,.85) 45%);border:1px solid rgba(248,113,113,.45);
  box-shadow:0 0 0 1px rgba(0,0,0,.25),0 8px 24px rgba(220,38,38,.16)}
