/* CAF data check */
.ck-bar{display:inline-block;width:70px;height:8px;border-radius:4px;background:var(--surface-3);vertical-align:middle;overflow:hidden}.ck-bar i{display:block;height:100%}
#main .tabs{gap:7px}#main .tabs .tab{padding:7px 14px;font-size:13px}

/* Dashboard case boxes */
.cs-row{display:grid;grid-template-columns:repeat(3,minmax(0,1fr)) minmax(220px,1.1fr);gap:12px;margin:0 0 16px}
.cs-box{--c:#3b82f6;display:flex;align-items:center;gap:12px;text-align:left;padding:14px 16px 22px;border-radius:14px;cursor:pointer;font:inherit;color:var(--text-primary);position:relative;overflow:hidden;
  border:1.5px solid color-mix(in srgb,var(--c) 55%,transparent);background:linear-gradient(135deg,color-mix(in srgb,var(--c) 30%,var(--surface-1)),color-mix(in srgb,var(--c) 8%,var(--surface-1)));transition:transform .15s,box-shadow .15s}
.cs-box:hover{transform:translateY(-2px);box-shadow:0 12px 26px -12px var(--c)}
.cs-all{--c:#3b82f6}.cs-done{--c:#10b981}.cs-pend{--c:#f97316}
.cs-ic{width:46px;height:46px;flex:0 0 46px;border-radius:12px;display:grid;place-items:center;font-size:22px;background:var(--c);box-shadow:0 6px 16px -6px var(--c)}
.cs-t{display:flex;flex-direction:column;line-height:1.25}.cs-t b{font-size:28px;color:color-mix(in srgb,var(--c) 30%,var(--text-primary))}.cs-t span{font-weight:700;font-size:14px}.cs-t small{color:var(--text-muted);font-size:11.5px}
.cs-go{position:absolute;right:12px;bottom:7px;font-size:11.5px;font-weight:700;color:var(--c)}
.cs-now{display:flex;flex-direction:column;gap:5px;align-items:flex-start;padding:12px 14px;border-radius:14px;border:1px solid var(--border);background:var(--surface-1)}
.cs-st{display:inline-block;padding:2px 10px;border-radius:999px;font-size:12px;font-weight:700}.cs-st.d{background:color-mix(in srgb,#10b981 22%,transparent);color:#10b981}.cs-st.p{background:color-mix(in srgb,#f97316 22%,transparent);color:#f97316}
[data-theme=light] .cs-t b{color:color-mix(in srgb,var(--c) 75%,#0f172a)}
@media (max-width:1100px){.cs-row{grid-template-columns:repeat(2,minmax(0,1fr))}}

/* small pill switch inside a card (same look as the page tabs) */
.pill-tabs{display:inline-flex;gap:6px;flex-wrap:wrap}
.pill-tabs button{--tc:#3b82f6;padding:6px 14px;border-radius:999px;font:inherit;font-size:13px;font-weight:700;cursor:pointer;color:var(--text-primary);
  border:1.5px solid color-mix(in srgb,var(--tc) 60%,transparent);background:linear-gradient(180deg,color-mix(in srgb,var(--tc) 28%,var(--surface-1)),color-mix(in srgb,var(--tc) 10%,var(--surface-1)));transition:transform .15s,box-shadow .15s}
