.pill-tabs button.on{color:#fff;text-shadow:0 1px 2px rgba(0,0,0,.4);background:linear-gradient(180deg,color-mix(in srgb,var(--tc) 82%,#fff),var(--tc));box-shadow:0 0 0 3px color-mix(in srgb,var(--tc) 28%,transparent)}
[data-theme=light] .pill-tabs button{background:linear-gradient(180deg,color-mix(in srgb,var(--tc) 18%,#fff),color-mix(in srgb,var(--tc) 6%,#fff));color:color-mix(in srgb,var(--tc) 55%,#0f172a)}
[data-theme=light] .pill-tabs button.on{color:#fff;background:linear-gradient(180deg,color-mix(in srgb,var(--tc) 85%,#fff),var(--tc))}

/* glance charts: click a bar / slice → records drawer */
.rec-click .it,.rec-click .lg-it{cursor:pointer}
#drawer.dr-wide{width:min(980px,72vw)}
.rec-kpi{display:flex;gap:10px;margin-bottom:12px;flex-wrap:wrap}
.rec-kpi>div{flex:1;min-width:120px;padding:10px 12px;border-radius:12px;background:linear-gradient(135deg,color-mix(in srgb,#8b5cf6 26%,var(--surface-2)),var(--surface-2));border:1px solid color-mix(in srgb,#8b5cf6 45%,var(--border))}
.rec-kpi>div:nth-child(2){background:linear-gradient(135deg,color-mix(in srgb,#10b981 26%,var(--surface-2)),var(--surface-2));border-color:color-mix(in srgb,#10b981 45%,var(--border))}
.rec-kpi>div:nth-child(3){background:linear-gradient(135deg,color-mix(in srgb,#f97316 26%,var(--surface-2)),var(--surface-2));border-color:color-mix(in srgb,#f97316 45%,var(--border))}
.rec-kpi b{display:block;font-size:22px}.rec-kpi span{font-size:12px;color:var(--text-muted)}

/* ===== New design for the count boxes (every page) ===== */
#main .kpis{gap:14px}
#main .kpi.kc2{border-radius:16px;padding:14px 16px 14px 18px;border:1.5px solid color-mix(in srgb,var(--kc) 60%,transparent);
