#main .kpi.kc2 .label{display:inline-block;padding:2px 9px;border-radius:999px;background:color-mix(in srgb,var(--kc) 24%,transparent);color:color-mix(in srgb,var(--kc) 40%,#fff);font-weight:800;letter-spacing:.5px}
#main .kpi.kc2 .value{color:#fff;text-shadow:0 2px 12px color-mix(in srgb,var(--kc) 55%,transparent)}
