/* IFSC lookup */
.ifsc-hero{display:flex;align-items:center;gap:14px;flex-wrap:wrap;background:linear-gradient(135deg,color-mix(in srgb,#0ea5e9 22%,var(--surface-1)),var(--surface-1) 70%)!important}
