.ifsc-card{margin-top:12px;padding:14px 16px;border-radius:14px;border:1.5px solid color-mix(in srgb,#0ea5e9 50%,var(--border));background:linear-gradient(135deg,color-mix(in srgb,#0ea5e9 14%,var(--surface-2)),var(--surface-2))}
