.g-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:8px 14px}.g-grid .wide{grid-column:1/-1}
.g-grid div{min-width:0}.g-grid span{display:block;font-size:10.5px;text-transform:uppercase;letter-spacing:.5px;color:var(--text-muted)}.g-grid b{font-size:13.5px;word-break:break-word}
