.g-fields button.on{background:linear-gradient(135deg,#4285F4,#7c3aed);border-color:transparent;color:#fff}.g-fields button.on small{color:#e0e7ff}
.g-ch .badge{max-width:45%;overflow:hidden;text-overflow:ellipsis}.g-ch>div{min-width:0}

/* home emblem: no dark shadow, no clipped edge around the spinning chakra */
.hp{overflow-x:hidden}
.hp-art{overflow:visible;contain:none}
.emblem-big{filter:drop-shadow(0 0 18px rgba(251,191,36,.18))!important}
.chakra-big{filter:drop-shadow(0 0 18px rgba(251,191,36,.35))!important}

/* home header: larger logo and readable text */
.hp-brand .hp-mark{width:96px;height:96px}
.hp-brand b{font-size:31px;line-height:1.15;letter-spacing:.3px}
.hp-brand .hp-hi{font-size:.92em;margin-left:8px}
.hp-brand small{font-size:14px;letter-spacing:1.8px;color:#cbd5e1;font-weight:600;margin-top:2px}
.hp-by{font-size:16.5px;margin-top:7px}.hp-by i{font-size:15px;padding:2px 12px}
.hp-top{padding:20px 0 18px}
@media (max-height:760px){.hp-brand .hp-mark{width:84px;height:84px}.hp-brand b{font-size:28px}.hp-top{padding:12px 0 12px}}
@media (max-width:620px){.hp-brand b{font-size:21px}.hp-brand .hp-mark{width:56px;height:56px}}

/* chakra: bright rays only, no dark disc or dark ray edges (no shadow inside the spinning part) */
.chakra-big{filter:none!important}
.hp-brand .hp-logo,.ck-wrap .emblem-sm{filter:none!important}

/* no glow behind the big or small logo */
.hp-ring{display:none!important}
.emblem-big,.chakra-big,.hp-brand .hp-logo,.ck,.ck-wrap .emblem-sm,.db-mark .emblem-sm,.emblem{filter:none!important;box-shadow:none!important}
/* hero name: Hindi and English balanced */
.hp-name{align-items:center;gap:6px 18px}
.hp-nen{font-size:clamp(28px,3vw,44px);letter-spacing:2.5px;line-height:1.1;font-weight:800;padding-left:18px;border-left:4px solid #f59e0b;color:#f1f5f9}
@media (max-height:760px){.hp-nen{font-size:clamp(24px,2.6vw,38px)}}
.hp-name{flex-wrap:nowrap}.hp-nhi{font-size:clamp(36px,3.6vw,60px);filter:none}.hp-nen{font-size:clamp(21px,2.25vw,38px);letter-spacing:1.6px;white-space:nowrap}
@media (max-height:760px){.hp-nen{font-size:clamp(20px,2.15vw,34px)}.hp-nhi{font-size:clamp(34px,3.4vw,52px)}}
@media (max-width:1000px){.hp-name{flex-wrap:wrap;justify-content:center}}

/* hero name: Hindi 20% smaller, no glow anywhere on heading or logos */
.hp-nhi{font-size:clamp(29px,2.9vw,48px)!important;text-shadow:none!important;filter:none!important}
@media (max-height:760px){.hp-nhi{font-size:clamp(27px,2.7vw,42px)!important}}
.hp-art,.hp-art *,.hp-brand,.hp-brand *,.ck-wrap,.ck-wrap *,.db-mark,.db-mark *,.lg-hi,.br-hi,.hp-hi{text-shadow:none!important;filter:none!important;box-shadow:none!important}
.hp-art::before,.hp-art::after,.ck-wrap::before,.ck-wrap::after,.db-mark::before,.db-mark::after{display:none!important}

/* hero name +20% with space below */
.hp-nhi{font-size:clamp(35px,3.48vw,58px)!important}
.hp-nen{font-size:clamp(25px,2.7vw,46px)!important}
@media (max-height:760px){.hp-nhi{font-size:clamp(32px,3.24vw,50px)!important}.hp-nen{font-size:clamp(24px,2.58vw,41px)!important}}
.hp-name{margin-bottom:22px!important}
@media (max-height:760px){.hp-name{margin-bottom:14px!important}}
.hp-name{column-gap:12px!important}.hp-nen{letter-spacing:1px!important;padding-left:14px!important}

/* Hindi name in Utsaah (Windows font); Nirmala UI / Noto as fallback */
[lang=hi],.hp-hi,.hp-nhi,.lg-hi,.br-hi,.db-hi{font-family:"Utsaah","Nirmala UI","Noto Sans Devanagari","Mangal","Kohinoor Devanagari",sans-serif!important}

/* Hindi name: room above and below so matras (ि ् ु) are never cut; the gradient text only paints inside the padding box */
.hp-nhi,.hp-hi,.lg-hi,.br-hi,.db-hi{display:inline-block;overflow:visible!important;padding-top:.28em!important;padding-bottom:.3em!important;margin-top:-.28em!important;margin-bottom:-.3em!important;padding-left:.06em;padding-right:.06em}
.hp-nhi{line-height:1.3!important}
.hp-name{column-gap:16px!important;padding-top:4px}

/* Brand name font: Mukta ExtraBold (Ek Type, SIL Open Font License 1.1), embedded so it works offline on every computer.
   One family designed for Hindi and English together, so both halves of the name match in weight and height. */
@font-face{font-family:"SA Brand";font-style:normal;font-weight:800;font-display:block;src:url(data:font/woff2;base64,) format("woff2");unicode-range:U+0900-097F,U+1CD0-1CF9,U+200C-200D,U+20A8,U+20B9,U+20F0,U+25CC,U+A830-A839,U+A8E0-A8FF}
@font-face{font-family:"SA Brand";font-style:normal;font-weight:800;font-display:block;src:url(data:font/woff2;base64,) format("woff2");unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+2000-206F,U+20AC,U+2122,U+2212,U+FEFF,U+FFFD}
[lang=hi],.hp-hi,.hp-nhi,.lg-hi,.br-hi,.db-hi{font-family:"SA Brand","Nirmala UI","Noto Sans Devanagari",sans-serif!important;font-weight:800!important;letter-spacing:0!important}
.hp-nen{font-family:"SA Brand","Segoe UI",sans-serif!important;font-weight:800!important}
/* hero name: Hindi and English in one font, Hindi letter body = English capital height */
.hp-name{align-items:baseline!important}
.hp-nhi{font-size:clamp(38px,3.7vw,62px)!important;line-height:1.3!important}
.hp-nen{font-size:clamp(30px,2.95vw,50px)!important;letter-spacing:1.5px!important;line-height:1.1!important}
@media (max-height:760px){.hp-nhi{font-size:clamp(35px,3.45vw,54px)!important}.hp-nen{font-size:clamp(28px,2.75vw,44px)!important}}
.hp-brand .hp-hi{font-size:1.05em!important}.br-hi{font-size:1.08em}
.hp-nhi{font-size:clamp(34px,3.25vw,55px)!important}@media (max-height:760px){.hp-nhi{font-size:clamp(31px,3.03vw,48px)!important}}

/* WhatsApp */
.w-sec{font-size:11px;font-weight:800;letter-spacing:1px;text-transform:uppercase;color:#25D366;margin:12px 0 4px}
.w-dl{background:#25D366!important;color:#fff}
.nowrap{white-space:nowrap}
.tbl td .ipv{overflow-wrap:anywhere;white-space:normal!important}
