/* Analysis › Tools */
.xt-subs{border-left-color:color-mix(in srgb,#f59e0b 40%,transparent)}
.nav-sub.xt-upl{color:#f59e0b;border-color:color-mix(in srgb,#f59e0b 55%,transparent)}
.nav-sub.xt-upl.active{background:color-mix(in srgb,#f59e0b 20%,transparent)}
.xt-head{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;border-left:4px solid var(--sc)!important}
.xt-head h3{color:var(--sc);margin:0}
