@media(max-width:900px){.tel-kinds{grid-template-columns:repeat(2,minmax(0,1fr))}}

/* telecom: Import Files & Folder menu */
.tel-impw{position:relative;display:inline-block}
.tel-menu{position:fixed;z-index:9000;background:var(--bg);border:1px solid var(--border);border-radius:12px;padding:6px;min-width:300px;box-shadow:0 14px 34px rgba(0,0,0,.4);text-align:left}
.tel-menu button{display:block;width:100%;text-align:left;background:none;border:0;color:var(--text-primary);padding:9px 10px;border-radius:8px;cursor:pointer;font-weight:600;font-size:14px}
.tel-menu button:hover{background:var(--surface-2)}
.tel-menu small{display:block;font-weight:400;color:var(--text-secondary);font-size:12px;margin-top:2px}

/* Dashboard: live number boxes (dashx.js) */
.dx-live{cursor:pointer;transition:transform .14s,box-shadow .14s,border-color .14s,filter .14s;outline:none}
.dx-live:hover,.dx-live:focus-visible{transform:translateY(-3px);box-shadow:0 10px 28px rgba(0,0,0,.35),0 0 0 2px color-mix(in srgb,var(--kc,var(--accent)) 70%,transparent);filter:brightness(1.08)}
.kpi.dx-live .dx-more{position:absolute;right:12px;bottom:9px;font-size:11px;font-weight:700;color:var(--kc,var(--accent));opacity:0;transform:translateX(-4px);transition:.14s}
.kpi.dx-live:hover .dx-more,.kpi.dx-live:focus-visible .dx-more{opacity:1;transform:none}
.step.dx-live{position:relative}
.step .dx-cnt{position:absolute;top:10px;right:12px;font-size:12px;font-weight:700;padding:2px 9px;border-radius:999px;background:var(--surface-3);color:var(--text-primary)}
.dx-tip{position:fixed;z-index:9500;pointer-events:none;background:var(--bg);border:1px solid var(--border);border-radius:12px;padding:10px 12px;box-shadow:0 16px 40px rgba(0,0,0,.45);opacity:0;transform:translateY(4px);transition:opacity .12s,transform .12s;font-size:12.5px}
.dx-tip.on{opacity:1;transform:none}
.dx-th{display:flex;justify-content:space-between;gap:8px;margin-bottom:6px}
.dx-th span{font-weight:700;color:var(--accent)}
.dx-tl div{display:flex;justify-content:space-between;gap:10px;padding:4px 0;border-top:1px solid var(--border)}
.dx-tl span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--text-secondary)}
.dx-tl b{white-space:nowrap;font-variant-numeric:tabular-nums}
.dx-tf{margin-top:6px;font-size:11px;color:var(--text-muted)}
#drawer.dx-wide{width:min(1100px,92vw)}
.dx-head{display:flex;gap:18px;align-items:center;margin-bottom:12px;flex-wrap:wrap}
.dx-head div{display:flex;flex-direction:column}
.dx-head b{font-size:20px;font-variant-numeric:tabular-nums}
.dx-head span{font-size:11px;color:var(--text-muted);text-transform:uppercase;letter-spacing:.6px}
.dx-head button{margin-left:auto}
.step.dx-live b{padding-right:30px;white-space:normal}
.kpis .kpi.dx-live{padding-bottom:28px}
.kpis .kpi.dx-live>.dx-more{position:absolute!important;right:14px!important;left:auto!important;bottom:9px!important;top:auto!important;margin:0!important;display:block}
.lea-find{width:calc(100% - 12px);margin:4px 6px 6px;padding:6px 9px;border-radius:8px;border:1px solid var(--border);background:var(--surface-2,var(--bg));color:var(--text-primary);font-size:12px}
.lea-subs.open{max-height:60vh;overflow-y:auto}
.lea-sub{display:flex;align-items:center;gap:6px}
.lea-sub .lea-ic{width:20px;text-align:center;flex:none}
.lea-sub .lea-ext{margin-left:auto;opacity:.55;font-size:11px}
.lea-sub:hover .lea-ext{opacity:1}
.lea-ed{max-height:52vh;overflow-y:auto;display:grid;gap:6px;padding-right:4px}
.lea-row{display:grid;grid-template-columns:22px 270px 1fr auto;gap:8px;align-items:center;font-size:13px;border-radius:8px;padding:1px 2px}
.lea-drag{cursor:grab;opacity:.6;font-size:16px;text-align:center;user-select:none}.lea-drag:hover{opacity:1}
.lea-mv{display:flex;gap:3px}.lea-mv .btn{padding:3px 7px;font-size:10px;line-height:1}
