@keyframes leaMv{from{background:color-mix(in srgb,#0ea5e9 35%,transparent)}to{background:transparent}}.lea-moved{animation:leaMv .8s ease}
.lea-nm{display:flex;align-items:center;gap:6px}.lea-nm .lea-ic{width:20px;text-align:center;flex:none}.lea-nm input{flex:1;min-width:0}
