.d2{display:grid;gap:16px;margin:0 0 16px}
.d2 .card{margin:0}
.d2-hd{display:flex;flex-wrap:wrap;align-items:baseline;gap:4px 12px;margin-bottom:10px}.d2-hd h3{margin:0}.d2-hd .sub{margin:0}
