/* Login: police-light badge */
.hp-kicker{position:relative;display:inline-flex;align-items:center;gap:12px;font-size:15px;font-weight:800;letter-spacing:2.4px;text-transform:uppercase;color:#fff;
  padding:9px 18px;border-radius:10px;overflow:hidden;isolation:isolate;
  background:linear-gradient(90deg,#1d4ed8 0%,#2563eb 30%,#7c3aed 50%,#dc2626 70%,#b91c1c 100%);
  border:1px solid rgba(255,255,255,.35);text-shadow:0 1px 2px rgba(0,0,0,.55),0 0 10px rgba(255,255,255,.35);
  box-shadow:0 0 18px rgba(37,99,235,.65),0 0 18px rgba(220,38,38,.55),inset 0 1px 0 rgba(255,255,255,.3);animation:hpSiren 1.6s ease-in-out infinite}
.hp-kicker span{position:relative;z-index:1}
.hp-kicker::before{content:'';position:absolute;inset:0;z-index:0;background:linear-gradient(110deg,transparent 30%,rgba(255,255,255,.28) 50%,transparent 70%);transform:translateX(-100%);animation:hpSweep 3.2s ease-in-out infinite}
.hp-kicker .sir{position:relative;z-index:1;width:11px;height:11px;border-radius:50%;flex:none}
.hp-kicker .sir.b{background:#93c5fd;box-shadow:0 0 6px #60a5fa,0 0 14px #3b82f6;animation:hpBlinkB 1.6s infinite}
.hp-kicker .sir.r{background:#fca5a5;box-shadow:0 0 6px #f87171,0 0 14px #ef4444;animation:hpBlinkR 1.6s infinite}
@keyframes hpSiren{0%,100%{box-shadow:-10px 0 24px rgba(37,99,235,.85),10px 0 10px rgba(220,38,38,.35),inset 0 1px 0 rgba(255,255,255,.3)}50%{box-shadow:-10px 0 10px rgba(37,99,235,.35),10px 0 24px rgba(220,38,38,.85),inset 0 1px 0 rgba(255,255,255,.3)}}
@keyframes hpBlinkB{0%,45%{opacity:1}55%,100%{opacity:.25}}
@keyframes hpBlinkR{0%,45%{opacity:.25}55%,100%{opacity:1}}
@keyframes hpSweep{0%{transform:translateX(-100%)}60%,100%{transform:translateX(100%)}}

/* Login: police shield badge */
.hp-kicker{overflow:visible;gap:12px;padding:8px 18px 8px 10px;cursor:default;transition:transform .25s ease}
.hp-kicker::before{border-radius:10px;overflow:hidden}
