  background:linear-gradient(160deg,#ef1c1c 0 50%,#1434e6 50% 100%);border:1px solid rgba(255,255,255,.7);box-shadow:0 0 10px rgba(255,255,255,.35)}
.hp-kicker:hover,.hp-kicker:focus-visible{transform:translateY(-2px) scale(1.04);outline:none}
.pk-pop{position:absolute;left:0;top:calc(100% + 12px);z-index:30;display:flex;gap:12px;align-items:center;width:max-content;max-width:min(460px,92vw);
  padding:12px 16px 12px 12px;border-radius:12px;background:#0b1630;border:1px solid rgba(147,197,253,.45);text-transform:none;letter-spacing:0;text-shadow:none;
  box-shadow:0 12px 30px rgba(0,0,0,.55),0 0 16px rgba(37,99,235,.45),0 0 16px rgba(220,38,38,.35);opacity:0;visibility:hidden;transform:translateY(-6px);transition:opacity .2s,transform .2s,visibility .2s;pointer-events:none}
.pk-pop::before{content:'';position:absolute;top:-7px;left:26px;width:12px;height:12px;background:#0b1630;border-left:1px solid rgba(147,197,253,.45);border-top:1px solid rgba(147,197,253,.45);transform:rotate(45deg)}
.pk-pop .pol-sh{width:46px;height:54px;margin:0}
.pk-pop b{display:block;font-size:14px;color:#fbbf24;font-weight:800;margin-bottom:3px}
