@keyframes hpSweep2{0%{background-position:150% 0}60%,100%{background-position:-50% 0}}
/* bigger police badge that always fits its text */
.hp-kicker{font-size:19px;letter-spacing:2px;padding:12px 24px 12px 14px;gap:14px;min-height:62px;max-width:100%;box-sizing:border-box;line-height:1.25;border-radius:12px}
