.bn-dot.r{background:#ef4444;box-shadow:0 0 6px #ef4444,0 0 14px #f87171;animation:bnSlow 2.4s ease-in-out infinite}.bn-due.done .bn-dot.g{animation:none;background:#22c55e;box-shadow:0 0 6px #22c55e}
@keyframes bnSlow{0%,100%{opacity:1;transform:scale(1.1)}50%{opacity:.15;transform:scale(.8)}}
.bn-due.bl-fr{border-color:#6b7280!important;background:rgba(107,114,128,.22)!important}.bn-due.bl-o{background:linear-gradient(135deg,#c2410c,#f97316 55%,#ea580c);border-color:#fdba74}.bn-due.bl-r{background:linear-gradient(135deg,#991b1b,#dc2626 55%,#b91c1c);border-color:#fca5a5}
@media (prefers-reduced-motion:reduce){.bn-dot.r{animation:none}}
/* Brand heading tidy-up (Vijay 14-11): name and Hindi name side by side, everything left-aligned, no stretched letters */
.hp-brand>div{display:flex!important;flex-direction:column;align-items:flex-start;width:auto;gap:3px}
.hp-brand>div>b{display:flex!important;justify-content:flex-start;align-items:baseline;gap:12px;font-size:32px!important;line-height:1.12;font-weight:800;letter-spacing:.2px;white-space:nowrap}
.hp-brand>div>b .hp-hi{margin-left:0!important;font-size:.95em!important;padding-left:12px!important;border-left:2px solid rgba(251,191,36,.45)}
.hp-brand>div>small{text-align:left!important;text-align-last:auto!important;letter-spacing:3px!important;font-size:12.5px!important;font-weight:700;color:#93c5fd!important;margin-top:0}
.hp-by.hp-one{display:inline-flex!important;justify-content:flex-start;gap:6px;font-size:11.5px!important;letter-spacing:1px!important;padding:3px 12px!important;margin-top:5px}
.hp-by.hp-one i{margin:0 4px!important}
.hp-onehi{text-align:left!important;text-align-last:auto!important;font-size:15px!important;margin-top:4px!important;color:#fde68a}
[data-theme=light] .hp-brand>div>small{color:#1d4ed8!important}
@media (max-width:900px){.hp-brand>div>b{font-size:24px!important}}
/* EO Enquiries table: readable columns (Vijay 14-11) */
#eoT .eo-vic{min-width:170px;max-width:260px}#eoT .eo-vic b{display:block;line-height:1.3;word-break:normal}
#eoT .eo-mob{display:block;white-space:nowrap;font-size:12px;color:var(--text-muted);margin-top:2px}
#eoT .eo-dt{white-space:nowrap}#eoT .eo-ty,#eoT .eo-st{white-space:nowrap}#eoT td.num{white-space:nowrap}
#eoT .eo-clip{display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;min-width:180px;max-width:300px;font-size:12.5px;line-height:1.4}
#eoT tbody tr.clickable:hover{background:rgba(99,102,241,.1)}
.eo-rtip{max-width:440px}.eo-rtip>div{margin-top:3px}.eo-rt-x{font-size:12px;opacity:.95;border-top:1px dashed rgba(148,163,184,.3);padding-top:3px}
.eo-view .eo-st{display:inline-block;margin-bottom:8px}.eo-view .eo-pre{white-space:pre-wrap;margin:4px 0 8px}
/* New login-page logo (Vijay 14-11): his emblem, white background removed, shown at full resolution; its own chakra replaces the spinning one */
.hp-art .chakra-big{display:none!important}
.hp-art .emblem.emblem-big{background-image:url(data:image/webp;base64,);aspect-ratio:1337/1005;height:auto!important;width:min(100%,640px);background-size:contain;animation:emIn .6s ease-out}
@media (max-height:760px){.hp-art .emblem.emblem-big{width:min(100%,560px)}}
@media (max-width:1000px){.hp-art .emblem.emblem-big{width:min(92vw,520px)}}
/* New round site logo (Vijay 14-11), HD 512 px; the golden sun-ray ring (.ck) keeps revolving around it */
.emblem.emblem-sm{background-image:url(data:image/webp;base64,)!important;border-radius:50%}
/* Login / home top bar (Vijay 14-11): right side reads Offline box, For Best View, Theme, Refresh, Login */
.hp-top .hp-pill{order:0!important;margin-left:auto}
.hp-th{display:inline-flex;align-items:center;justify-content:center;width:44px;height:44px;padding:0;border-radius:12px;cursor:pointer;color:#fbbf24;background:rgba(245,158,11,.12);border:1px solid rgba(245,158,11,.45);font:inherit}
.hp-th:hover{background:rgba(245,158,11,.25);border-color:#fbbf24}.hp-th svg{transition:transform .4s}.hp-th:hover svg{transform:rotate(25deg)}
[data-theme=light] .hp-th{color:#b45309;background:#fffbeb;border-color:#fcd34d}
.hp-top{gap:10px}.hp-top .hp-pill{max-width:530px}.hp-top .hp-pill .hp-pt{white-space:normal;line-height:1.3}
@media (max-width:1700px){.hp-top .hp-pill{max-width:380px}.hp-top .hp-pill .hp-pt{font-size:12.5px}}
@media (max-width:1500px){.hp-top .hp-pill{order:9!important;max-width:none}.hp-top .bv-wrap{margin-left:auto}}
/* Day (light) theme for the login / home page (Vijay 14-11): light page, dark text, clear box outlines */
[data-theme=light] #login{color:#0f172a;background:radial-gradient(900px 520px at 78% 30%,rgba(245,158,11,.14),transparent 60%),radial-gradient(1000px 600px at 10% 0%,rgba(59,130,246,.12),transparent 60%),linear-gradient(rgba(15,23,42,.05) 1px,transparent 1px) 0 0/44px 44px,linear-gradient(90deg,rgba(15,23,42,.05) 1px,transparent 1px) 0 0/44px 44px,#f6f8fc}
[data-theme=light] .hp-top{border-bottom-color:rgba(15,23,42,.12)}
[data-theme=light] .hp-brand>div>b{background:linear-gradient(90deg,#0f2a5c,#1e3a8a 55%,#c2410c);-webkit-background-clip:text;background-clip:text;color:transparent}
[data-theme=light] .hp-onehi{color:#9a3412!important}
[data-theme=light] .hp-pill{color:#065f46;background:#ecfdf5;border-color:#34d399}[data-theme=light] .hp-pill b{color:#047857}[data-theme=light] .hp-pill small{color:#065f46}
[data-theme=light] .hp-lead{color:#334155}
[data-theme=light] .hp-feat{background:#fff;border-color:#e2e8f0;box-shadow:0 2px 10px rgba(15,23,42,.06)}[data-theme=light] .hp-feat p{color:#475569}[data-theme=light] .hp-feat h3,[data-theme=light] .hp-feat b{color:#0f172a}
[data-theme=light] .hp-trust li{background:#fff;border-color:#e2e8f0;color:#334155}
[data-theme=light] .hp-foot{color:#475569;border-top-color:rgba(15,23,42,.12)}
[data-theme=light] .hp-btn2{color:#1e3a8a;border-color:#93c5fd;background:#eff6ff}
[data-theme=light] .hp-copy h1{color:#0f172a!important}[data-theme=light] .hp-copy h1 span{color:transparent!important}
